    14	
    15	export interface Scenario {
    16	  readonly customer: Customer;
    17	  readonly steps: readonly Step[];
    18	}
    19	
    20	export interface QuoteResult {
    21	  readonly premium: number;
    22	}
    23	
    24	export type StepResult = QuoteResult;
    25	
    26	export interface ScenarioResults {
    27	  readonly results: readonly StepResult[];
    28	}
