    30	/**
    31	 * The steps of a scenario are processed in order for one customer, and each
    32	 * quote after the customer's first is a follow-up contract.
    33	 */
    34	export function runScenario(scenario: Scenario): ScenarioResults {
    35	  const results: StepResult[] = [];
    36	  let previousContracts = 0;
    37	  for (const step of scenario.steps) {
    38	    results.push({
    39	      premium: quote(scenario.customer, step.items, previousContracts),
    40	    });
    41	    previousContracts += 1;
    42	  }
    43	  return { results };
    44	}
