     1	import type { Customer } from "./policy.js";
     2	
     3	/**
     4	 * Policy-wide modifiers scale the policy base premium (the sum of all item
     5	 * base premiums). Item-specific modifiers live with the items they affect.
     6	 *
     7	 * Three independent policies live here, and they answer to different facts:
     8	 * the initial assessment surcharge is a property of the quote itself, the
     9	 * loyalty discount is a property of the customer's relationship with the
    10	 * MHPCO, and the follow-up contract discount is a property of the
    11	 * customer's contract history in this scenario.
    12	 *
    13	 * Each is expressed as a signed adjustment to the policy base premium, so
    14	 * that a surcharge and a discount differ only in sign and the quote can sum
    15	 * them without knowing which is which.
    16	 */
    17	
    18	/** Long-standing customers are rewarded with a loyalty discount. */
    19	const LOYALTY_DISCOUNT_RATE = 0.2;
    20	const LOYALTY_YEARS = 2;
    21	
    22	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
    23	
    24	/** Every contract after the customer's first is discounted. */
    25	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    26	
    27	/** What the quote is assessed against, beyond the items themselves. */
    28	export interface Contract {
    29	  readonly customer: Customer;
    30	  /** Contracts this customer already holds in the scenario. */
    31	  readonly previousContracts: number;
    32	}
    33	
    34	function isLongStanding(customer: Customer): boolean {
    35	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
    36	}
    37	
    38	/** A follow-up contract is any contract after the customer's first. */
    39	function isFollowUpContract(contract: Contract): boolean {
    40	  return contract.previousContracts > 0;
    41	}
    42	
    43	/** Long-standing customers are rewarded off the premium. */
    44	function loyaltyDiscount(contract: Contract, policyBasePremium: number): number {
    45	  return isLongStanding(contract.customer)
    46	    ? -policyBasePremium * LOYALTY_DISCOUNT_RATE
    47	    : 0;
    48	}
    49	
    50	function followUpContractDiscount(
    51	  contract: Contract,
    52	  policyBasePremium: number,
    53	): number {
    54	  return isFollowUpContract(contract)
    55	    ? -policyBasePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
    56	    : 0;
    57	}
    58	
    59	/**
    60	 * Every item in a quote is assessed as a first insurance, regardless of
    61	 * customer history, so this surcharge always applies.
    62	 */
    63	function initialAssessmentSurcharge(policyBasePremium: number): number {
    64	  return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
    65	}
    66	
    67	/**
    68	 * The net signed adjustment the policy-wide modifiers make to the policy
    69	 * base premium: positive for a surcharge, negative for a discount.
    70	 */
    71	export function policyWideAdjustment(
    72	  contract: Contract,
    73	  policyBasePremium: number,
    74	): number {
    75	  return (
    76	    initialAssessmentSurcharge(policyBasePremium) +
    77	    loyaltyDiscount(contract, policyBasePremium) +
    78	    followUpContractDiscount(contract, policyBasePremium)
    79	  );
    80	}
===== premium-contribution.ts =====
     1	/**
     2	 * What insured items contribute to a premium, before policy-wide modifiers.
     3	 *
     4	 * The two contributions are kept apart all the way up because policy-wide
     5	 * modifiers scale only the policy base premium: a risk surcharge has already
     6	 * been assessed against its own item and must not be scaled again.
     7	 */
     8	export interface ItemPricing {
     9	  /** Sum of item base premiums -- the policy base premium. */
    10	  readonly basePremium: number;
    11	  /** Item-specific risk surcharges, each on its own item's base premium. */
    12	  readonly riskSurcharges: number;
    13	}
    14	
    15	/** An item that contributes nothing -- the identity for combining pricings. */
    16	export const NO_PRICING: ItemPricing = { basePremium: 0, riskSurcharges: 0 };
    17	
    18	/**
    19	 * Pricings combine by adding each contribution separately: base premiums
    20	 * accumulate into the policy base premium, and risk surcharges accumulate
    21	 * alongside it, because policy-wide modifiers scale only the former.
    22	 */
    23	export function combinedPricing(
    24	  left: ItemPricing,
    25	  right: ItemPricing,
    26	): ItemPricing {
    27	  return {
    28	    basePremium: left.basePremium + right.basePremium,
    29	    riskSurcharges: left.riskSurcharges + right.riskSurcharges,
    30	  };
    31	}
    32	
    33	/** What a whole group of priced items contributes, combined. */
    34	export function combinedPricings(
    35	  pricings: readonly ItemPricing[],
    36	): ItemPricing {
    37	  return pricings.reduce(combinedPricing, NO_PRICING);
    38	}

