import type { Customer, Item } from "./policy.js";
import { quote } from "./quote.js";

/**
 * A scenario arrives as JSON, so a step's `op` is read as the string it was
 * written as rather than as a narrowed literal type. Nothing here has
 * established that the string is one the MHPCO recognises: narrowing it is
 * the CLI's job, at the boundary where an unrecognised step is refused with
 * a non-zero exit, and a literal type here would claim a guarantee no code
 * has yet made.
 */
export interface QuoteStep {
  readonly op: string;
  readonly items: readonly Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  readonly customer: Customer;
  readonly steps: readonly Step[];
}

export interface QuoteResult {
  readonly premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResults {
  readonly results: readonly StepResult[];
}

/**
 * What the customer has accumulated over the scenario so far, and so what a
 * step is assessed against when it is reached.
 *
 * This is the scenario's own running state rather than anything a single
 * step knows: a step settles under the history it finds, and leaves a
 * history behind for the steps after it.
 */
interface ContractHistory {
  /** Contracts the customer already holds when this step is reached. */
  readonly previousContracts: number;
}

const NO_CONTRACTS_YET: ContractHistory = { previousContracts: 0 };

/** Taking out a contract is what adds to the customer's contract history. */
function withContractTakenOut(history: ContractHistory): ContractHistory {
  return { previousContracts: history.previousContracts + 1 };
}

/** What a step settles at, and the history it leaves for the steps after it. */
interface SettledStep {
  readonly result: StepResult;
  readonly history: ContractHistory;
}

/**
 * What one step settles at, under the customer it is quoted for and the
 * history it is reached with.
 *
 * Which decision a step calls for is stated here, apart from the order the
 * scenario runs them in: what an operation settles at and how a scenario is
 * walked are revised on their own schedules -- a new operation changes this
 * and leaves the walk alone, and neither touches the other's names.
 *
 * A quote is a contract taken out, so it is a quote -- not merely a step --
 * that advances the contract history the follow-up discount reads.
 */
function settle(
  customer: Customer,
  step: Step,
  history: ContractHistory,
): SettledStep {
  return {
    result: { premium: quote(customer, step.items, history.previousContracts) },
    history: withContractTakenOut(history),
  };
}

/**
 * The steps of a scenario are processed in order for one customer, each
 * settled under the history the steps before it left, and each contributing
 * one result in its own position.
 */
export function runScenario(scenario: Scenario): ScenarioResults {
  const results: StepResult[] = [];
  let history = NO_CONTRACTS_YET;
  for (const step of scenario.steps) {
    const settled = settle(scenario.customer, step, history);
    results.push(settled.result);
    history = settled.history;
  }
  return { results };
}

